`debounce(fn, wait)` возвращает новую функцию, которая откладывает вызов `fn` до тех пор, пока не пройдёт `wait` мс с последнего вызова. В варианте `trailing` функция вызывается в конце паузы, в `leading` — сразу при первом вызове; обычно полезно поддержать обе опции и метод `cancel()`, чтобы снять запланированный таймер. Ниже минимальная реализация:

```js
function debounce(fn, wait, { leading = false, trailing = true } = {}) {
  let timeoutId = null;
  let lastArgs;
  let lastThis;
  let hasLeadingCalled = false;

  function cancel() {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    hasLeadingCalled = false;
  }

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const shouldCallNow = leading && !timeoutId;
    if (shouldCallNow) {
      hasLeadingCalled = true;
      fn.apply(lastThis, lastArgs);
    }

    if (timeoutId !== null) clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && (!leading || hasLeadingCalled)) {
        fn.apply(lastThis, lastArgs);
      }
      hasLeadingCalled = false;
    }, wait);
  }

  debounced.cancel = cancel;
  return debounced;
}
```

Для модалки базовый набор такой: контейнер с `role="dialog"`, `aria-modal="true"`, связывание заголовка через `aria-labelledby`, сохранение активного элемента перед открытием и возврат фокуса при закрытии. При открытой модалке фокус должен оставаться внутри неё, а прокрутку фона обычно блокируют; клавиша `Esc` закрывает окно. Минимальный пример:

```html
<button id="open">Open modal</button>

<div id="backdrop" hidden>
  <div id="modal" role="dialog" aria-modal="true" aria-labelledby="title">
    <h2 id="title">Settings</h2>
    <button id="close">Close</button>
    <input placeholder="First focusable" />
  </div>
</div>

<script>
  const openBtn = document.getElementById('open');
  const closeBtn = document.getElementById('close');
  const backdrop = document.getElementById('backdrop');
  const modal = document.getElementById('modal');
  let lastFocused = null;

  const focusables = () => modal.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');

  function openModal() {
    lastFocused = document.activeElement;
    backdrop.hidden = false;
    document.body.style.overflow = 'hidden';
    focusables()[0]?.focus();
    document.addEventListener('keydown', onKeyDown);
  }

  function closeModal() {
    backdrop.hidden = true;
    document.body.style.overflow = '';
    document.removeEventListener('keydown', onKeyDown);
    lastFocused?.focus();
  }

  function onKeyDown(e) {
    if (e.key === 'Escape') closeModal();
    if (e.key !== 'Tab') return;

    const items = [...focusables()];
    const first = items[0];
    const last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last?.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first?.focus();
    }
  }

  openBtn.addEventListener('click', openModal);
  closeBtn.addEventListener('click', closeModal);
</script>
```

Ниже — минимальный вариант на plain JS: кнопка открывает список, стрелки меняют активный пункт, Enter выбирает, Escape закрывает и возвращает фокус на кнопку. Для кастомного дропдауна важно держать фокус управляемым, а для состояния — обновлять `aria-expanded` и использовать подходящий pattern (`button` + `listbox`/`option` или `menu`/`menuitem`, в зависимости от поведения). ```html
<button id="btn" aria-expanded="false" aria-controls="list">Choose</button>
<ul id="list" role="listbox" hidden>
  <li role="option" tabindex="-1">One</li>
  <li role="option" tabindex="-1">Two</li>
  <li role="option" tabindex="-1">Three</li>
</ul>
<script>
const btn = document.getElementById('btn');
const list = document.getElementById('list');
const options = [...list.querySelectorAll('[role="option"]')];
let index = -1;
function open() { list.hidden = false; btn.setAttribute('aria-expanded','true'); index = 0; options[0].focus(); }
function close() { list.hidden = true; btn.setAttribute('aria-expanded','false'); btn.focus(); }
btn.addEventListener('click', () => list.hidden ? open() : close());
list.addEventListener('keydown', e => {
  if (e.key === 'ArrowDown') { e.preventDefault(); options[(index = (index + 1) % options.length)].focus(); }
  if (e.key === 'ArrowUp') { e.preventDefault(); options[(index = (index - 1 + options.length) % options.length)].focus(); }
  if (e.key === 'Enter') { e.preventDefault(); btn.textContent = options[index].textContent; close(); }
  if (e.key === 'Escape') { e.preventDefault(); close(); }
});
</script>
```

`Promise.then()` и `queueMicrotask()` ставят работу в очередь микрозадач; браузер выполняет микрозадачи до того, как снова перейдёт к очередному шагу event loop и сможет обновить рендеринг. Если микрозадачи длинные или постоянно добавляют новые микрозадачи, основной поток не получает «окно» на отрисовку, поэтому кадры пропускаются и UI начинает фризить. Чтобы разбить тяжёлую работу, вынесите вычисления в Web Worker, а если код должен остаться на main thread — обрабатывайте данные чанками и делайте паузы через `postMessage`/`MessageChannel` или `requestIdleCallback` с fallback; для DOM отдельно батчите чтения и записи, чтобы не вызывать layout thrashing. ```js
// пример порционного процессинга
function processChunks(items, fn, chunkSize = 100) {
  let i = 0;
  function step() {
    const end = Math.min(i + chunkSize, items.length);
    for (; i < end; i++) fn(items[i]);
    if (i < items.length) setTimeout(step, 0);
  }
  step();
}
```

```js
class MyError extends Error {
  constructor(message) {
    super(message);
    this.name = 'MyError';
  }
}
```
Собственный класс ошибки удобен, когда нужно отличать типы ошибок через `instanceof` или `name` и обрабатывать их по-разному. При наследовании от `Error` важно вызвать `super()`, иначе объект ошибки не будет корректно инициализирован; затем обычно явно задают `name`, чтобы сообщение и стек были диагностически полезны. В современных движках наследование от `Error` работает как часть стандартной модели ошибок.

Вывод будет таким: `start`, `end`, `promise`, `timeout`. Синхронный код выполняется первым, затем движок опустошает очередь microtasks, поэтому обработчик `Promise.then()` запускается раньше `setTimeout(..., 0)`, который попадает в очередь tasks. В Node.js есть ещё `process.nextTick()`: он выполняется раньше microtasks в CommonJS, но в ESM нюансы могут отличаться, поэтому для переносимого кода лучше ориентироваться на `queueMicrotask()` и Promise-макеты задач.

```js
console.log('start');
setTimeout(() => console.log('timeout'), 0);
Promise.resolve().then(() => console.log('promise'));
console.log('end');
// start
// end
// promise
// timeout
```

Геттеры и сеттеры — это accessor properties: при чтении или записи свойства выполняется функция, поэтому доступ к `obj.x` может иметь побочные эффекты. Главная ловушка — рекурсия, когда внутри `get x()` или `set x(v)` снова обращаются к `this.x`: это вызывает тот же accessor ещё раз. Обычно это обходят через отдельное внутреннее поле, например `this._x` или `#x`, либо через `Symbol`, чтобы API свойства не зацикливался сам на себе.

```js
class User {
  #name = '';
  get name() { return this.#name; }
  set name(v) { this.#name = String(v); }
}
```

`as const` включает const assertion: TypeScript перестаёт расширять литеральные типы, делает свойства объекта `readonly`, а массивы — `readonly` кортежами. Это полезно, когда нужно сохранить точные значения, например для списков вариантов, конфигов или discriminated union.

```ts
const arr = ["a", 1] as const; // readonly ["a", 1]
const obj = { kind: "ok", code: 200 } as const;
// obj.kind имеет тип "ok", obj.code — 200
```

Да, через `extends` можно ограничить допустимые типы для дженерика. Например, функция ниже принимает любой объект, у которого есть `id: number`, и безопасно читает это поле без `any`.

```ts
function getId<T extends { id: number }>(obj: T): number {
  return obj.id;
}
```

Свой type guard пишут как функцию с return type-предикатом `x is Type`. Такая функция возвращает `boolean`, но для TypeScript её `true`-ветка означает: аргумент можно считать типом `Type`. В результате после вызова в `if` компилятор сужает тип переменной.

```ts
type User = { id: number; name: string };

function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    "id" in value &&
    typeof (value as any).id === "number" &&
    "name" in value &&
    typeof (value as any).name === "string"
  );
}
```

`never` — это тип невозможного значения: он встречается у функций, которые не завершаются нормально, например всегда бросают исключение или зациклены. Ещё `never` полезен для exhaustive check в `switch` по discriminated union: если в `default` значение ещё имеет тип, значит вы не обработали все варианты.

```ts
function fail(message: string): never {
  throw new Error(message);
}

type Shape = { type: "circle"; r: number } | { type: "square"; size: number };

function area(s: Shape) {
  switch (s.type) {
    case "circle": return Math.PI * s.r ** 2;
    case "square": return s.size ** 2;
    default: {
      const _exhaustive: never = s;
      return _exhaustive;
    }
  }
}
```

`isUser(obj): obj is User` — это user-defined type guard: функция возвращает `boolean`, но при `true` TypeScript считает аргумент типом `User`. Обычно внутри такой функции проверяют, что объект не `null`, является объектом, и что нужные поля существуют и имеют правильные типы. После вызова в `if` компилятор сужает тип переменной до `User`.

```ts
type User = { id: number; name: string };

function isUser(obj: unknown): obj is User {
  return (
    typeof obj === "object" &&
    obj !== null &&
    "id" in obj &&
    typeof (obj as any).id === "number" &&
    "name" in obj &&
    typeof (obj as any).name === "string"
  );
}
```

В `switch` нужно сужать union по дискриминанту `kind`, а в ветке `default` или после всех `case` делать проверку на `never`: если в union появится новый вариант, присваивание сломается на компиляции. Такой приём работает вместе с exhaustive checking для discriminated unions.

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; size: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.radius ** 2;
    case "square":
      return s.size ** 2;
    default: {
      const _exhaustive: never = s;
      return _exhaustive;
    }
  }
}
```

Ограничение пишется так: `function getProp<T, K extends keyof T>(obj: T, key: K): T[K]`. `keyof T` даёт допустимые имена свойств объекта `T`, а `T[K]` — тип значения по этому ключу.

```ts
function getProp<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}
```

Mapped type строится по шаблону `{ [P in keyof T]: ... }`: TypeScript проходит по каждому ключу `T` и собирает новый тип. `Partial<T>` вручную можно записать как `{ [P in keyof T]?: T[P] }`, а `Readonly<T>` — как `{ readonly [P in keyof T]: T[P] }`. Знак `?` делает все свойства опциональными, а `readonly` — неизменяемыми.

```ts
type MyPartial<T> = { [P in keyof T]?: T[P] };
type MyReadonly<T> = { readonly [P in keyof T]: T[P] };
```

`Pick<T, K>` выбирает из типа только указанные свойства, `Omit<T, K>` — наоборот, убирает указанные свойства, а `Record<K, T>` строит объектный тип с ключами `K` и значениями `T`. `Pick` удобно использовать для DTO и подмножеств моделей, `Omit` — для исключения лишних полей, `Record` — для словарей и маппинга по заранее известному набору ключей.

```ts
type User = { id: string; name: string; email: string };
type UserPreview = Pick<User, "id" | "name">;
type PublicUser = Omit<User, "email">;
type RoleMap = Record<"admin" | "user", boolean>;
```

`default`-экспорт — это один основной экспорт модуля: `export default ...`, а named-экспортов может быть много: `export const x = ...`, `export { x }`. Соответственно, импорт выглядит как `import x from "..."` для default и `import { x } from "..."` для named. Опция `esModuleInterop` меняет совместимость с CommonJS-модулями: она упрощает и выравнивает поведение default- и namespace-import'ов при трансляции TypeScript-кодом.

```ts
export default function fn() {}
export const helper = 1;
```

Declaration merging — это слияние нескольких объявлений с одним именем в одну сущность; классический случай — несколько `interface` с одинаковым именем. `interface` можно «открывать» и расширять, поэтому его удобно использовать для расширения публичных API и ambient declarations. `type alias` не участвует в merging, зато лучше подходит для union, intersection и любых сложных выражений типов.

```ts
interface Foo { a: string }
interface Foo { b: number }
// Foo = { a: string; b: number }
```

Самая стандартная реализация: `type Omit<T, K extends keyof any> = Pick<T, Exclude<keyof T, K>>`. Здесь `Exclude` убирает ключи `K` из `keyof T`, а `Pick` собирает новый тип только из оставшихся свойств.

```ts
type User = {
  id: string;
  email: string;
  password: string;
};

type PublicUser = Omit<User, "password">;
// { id: string; email: string }
```

`import type` и `export type` удаляются из сгенерированного JavaScript, поэтому они не создают runtime-binding. Если попытаться использовать такой импорт как значение, в рантайме получится `undefined` или другая ошибка, потому что TypeScript оставил только типовую информацию, а не реальный импорт. Чтобы этого избежать, нужно импортировать значения обычным `import`, а type-only imports использовать только для типов; также полезны правила линтера и проверки, которые не дают обращаться к типам как к значениям.

```ts
import { type Foo } from "./foo";
// Foo нельзя использовать как значение
```

```js
// Плохо: многократно чередуем чтение layout и запись в DOM.
const items = [...document.querySelectorAll('.item')];
for (const el of items) {
  const w = el.getBoundingClientRect().width; // forced read
  el.style.width = `${w + 10}px`;            // write
}

// Лучше: сначала все читаем, потом все пишем.
const widths = items.map((el) => el.getBoundingClientRect().width);
requestAnimationFrame(() => {
  items.forEach((el, i) => {
    el.style.width = `${widths[i] + 10}px`;
  });
});
```
Суть оптимизации — не смешивать чтения и записи в одном цикле, чтобы не провоцировать repeated layout/reflow. Если нужно создать много новых узлов, лучше собрать их во временном `DocumentFragment` или одной HTML-строкой, а затем вставить один раз.

```jsx
import { useEffect } from 'react';

function Widget({ topic, onTopicChange }) {
  useEffect(() => {
    const handler = () => console.log('event');
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);

  useEffect(() => {
    onTopicChange(topic);
  }, [topic, onTopicChange]);

  return null;
}
```
Первый `useEffect` имитирует `componentDidMount`/`componentWillUnmount`: подписка создаётся один раз, а cleanup снимает её при размонтировании. Второй `useEffect` реагирует на смену `topic`, поэтому `topic` и `onTopicChange` должны быть в списке зависимостей; если логика независима, эффекты лучше разделять, чтобы зависимостями было проще управлять.

```jsx
import { useEffect, useState } from 'react';

export function useDebouncedValue(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(id);
  }, [value, delay]);

  return debouncedValue;
}
```

В `<script setup lang="ts">` props можно типизировать либо через `defineProps<T>()` для type-only объявления, либо через `defineProps({ ... })` для runtime-валидации. Дефолты для type-only props задают через `withDefaults(defineProps<T>(), { ... })`; для массивов и объектов дефолт лучше передавать фабрикой, чтобы каждая инстанция компонента получала свою копию. Подвох в том, что `optional` в TypeScript и `required` в runtime — это не одно и то же: без `withDefaults` проп может быть опциональным в типах, но фактически ожидаться как обязательный в логике компонента. Деструктуризация `defineProps()` в Vue 3.5+ стала реактивной, но в более старых версиях она могла терять реактивность, поэтому для совместимости лучше не полагаться на голую деструктуризацию.```ts
interface Props {
  msg?: string
  labels?: string[]
}

const props = withDefaults(defineProps<Props>(), {
  msg: 'hello',
  labels: () => ['one', 'two'],
})
```

Да, это типичный composable: внутри `useResizeWidth()` храните ширину в `ref`, считывайте `window.innerWidth` в обработчике и подписывайтесь в `onMounted()`, а отписывайтесь в `onUnmounted()`. Для SSR доступ к `window` должен быть только после монтирования. Минимальный вариант:

```ts
import { ref, onMounted, onUnmounted } from 'vue'

export function useResizeWidth() {
  const width = ref(0)

  const update = () => {
    width.value = window.innerWidth
  }

  onMounted(() => {
    update()
    window.addEventListener('resize', update)
  })

  onUnmounted(() => {
    window.removeEventListener('resize', update)
  })

  return { width }
}
```

Ниже минимальный composable: он хранит id интервала в `ref`, даёт `start()` и `stop()`, и очищает таймер при размонтировании через `onScopeDispose()`. Такой вариант корректен для использования внутри `setup()` и не оставляет «висячих» интервалов. ```ts
import { ref, onScopeDispose, type Ref } from 'vue'

export function useInterval(callback: () => void, delay: number | Ref<number>) {
  const id = ref<ReturnType<typeof setInterval> | null>(null)

  const stop = () => {
    if (id.value !== null) {
      clearInterval(id.value)
      id.value = null
    }
  }

  const start = () => {
    stop()
    const ms = typeof delay === 'number' ? delay : delay.value
    id.value = setInterval(callback, ms)
  }

  onScopeDispose(stop)
  return { start, stop }
}
```

```js
import { ref } from 'vue'

export function useCounter(initialValue = 0) {
  const count = ref(initialValue)

  const inc = () => count.value++
  const dec = () => count.value--
  const reset = () => (count.value = initialValue)

  return { count, inc, dec, reset }
}
```
Такой composable не хранит общий мутируемый стейт между вызовами, поэтому его можно безопасно использовать в нескольких компонентах. В тестах важно создавать новый экземпляр composable на каждый кейс и отдельно проверять реакцию на начальное значение и reset; для SSR — не делать DOM-зависимых действий вне `onMounted()`, а всё побочное поведение убирать в `onUnmounted()`.

Базовый паттерн в Pinia такой: объявляете стор через `defineStore()`, а в компоненте Composition API вызываете `useStore()` внутри `setup()` или `<script setup>`. В Nuxt Pinia подключают через модуль `@pinia/nuxt`, а для использования стора вне `setup()` или инъекционного контекста нужно передать в `useStore()` конкретный `pinia`-инстанс. Для SSR важно не шарить одно и то же состояние между запросами: Nuxt берёт на себя значительную часть SSR-интеграции, а сторы должны быть привязаны к текущему приложению/запросу, а не к модульному singleton.```ts
export const useCounterStore = defineStore('counter', () => {
  const count = ref(0)
  const double = computed(() => count.value * 2)
  function increment() { count.value++ }
  return { count, double, increment }
})

const counter = useCounterStore()
```

Ниже минимальная реализация директивы: обработчик хранится на элементе, при обновлении он заменяется, а при размонтировании удаляется. `binding.value` — это переданная функция; `binding.modifiers.self` можно трактовать как дополнительное условие, например игнорировать клики по самому элементу. Для SSR нужно не трогать `window`/`document` без проверки окружения.

```js
const vClickOutside = {
  beforeMount(el, binding) {
    if (typeof window === 'undefined') return

    const handler = (event) => {
      if (binding.modifiers.self && event.target === el) return
      if (!el.contains(event.target)) binding.value?.(event)
    }

    el._vClickOutside = handler
    document.addEventListener('click', handler)
  },
  updated(el, binding) {
    if (el._vClickOutside) {
      document.removeEventListener('click', el._vClickOutside)
    }
    const handler = (event) => {
      if (binding.modifiers.self && event.target === el) return
      if (!el.contains(event.target)) binding.value?.(event)
    }
    el._vClickOutside = handler
    document.addEventListener('click', handler)
  },
  beforeUnmount(el) {
    document.removeEventListener('click', el._vClickOutside)
    delete el._vClickOutside
  }
